export interface WorksiteCommandExecutionHelperPlan {
  readonly kind: "worksite_command_execution_helper_plan";
  readonly schemaVersion: "5.0.0";
  readonly attemptRef: string;
  readonly helperModulePath: string;
  readonly taskManifestPath: string;
  readonly taskManifestDigest: Sha256Digest;
  readonly taskManifestByteLength: number;
  readonly artifactPath: string;
  readonly sandboxRoot: string;
  readonly toolCommand: string;
  readonly toolInputDigest: Sha256Digest;
  readonly toolInputByteLength: number;
}

export function worksiteCommandExecutionHelperPlan(
  task: WorksiteExecutionTask,
  attemptRef: string,
): WorksiteCommandExecutionHelperPlan {
  return helperPlanForExecutable(task, attemptRef, process.execPath);
}

function helperPlanForExecutable(
  task: WorksiteExecutionTask,
  attemptRef: string,
  executable: string,
): WorksiteCommandExecutionHelperPlan {
  if (!isWorksiteExecutionTask(task) || !nonempty(attemptRef) ||
    !nonempty(executable) || !isAbsolute(executable)) {
    throw new TypeError("command helper plan requires one exact task, attempt identity, and absolute executable");
  }
  const helperModulePath = join(
    task.workspaceBinding.roots.toolchainRoot,
    "node_modules", "@abiogenesis", "typescript-tenant", "build", "code", "src",
    "implementation", "worksite_command_helper.js",
  );
  const attemptDigest = sha256Canonical({ attemptRef });
  const attemptRoot = join(
    task.workspaceBinding.roots.archiveRoot,
    "worksite-command-execution",
    task.taskDigest.slice("sha256:".length),
    attemptDigest.slice("sha256:".length),
  );
  const taskManifestPath = join(attemptRoot, "task.json");
  const launchManifestPath = join(dirname(taskManifestPath), "launch.json");
  const artifactPath = join(attemptRoot, "result.json");
  const sandboxRoot = join(attemptRoot, "sandbox");
  const taskBytes = Buffer.from(`${canonicalJson(task as unknown as JsonValue)}\n`, "utf8");
  const toolCommand = [
    shellQuote(executable), shellQuote(helperModulePath),
    "--task", shellQuote(launchManifestPath),
  ].join(" ");
  const toolInputBytes = Buffer.from(canonicalJson({ command: toolCommand }), "utf8");
  return deepFreeze({
    kind: "worksite_command_execution_helper_plan" as const,
    schemaVersion: SCHEMA_VERSION,
    attemptRef,
    helperModulePath,
    taskManifestPath,
    taskManifestDigest: sha256Bytes(taskBytes),
    taskManifestByteLength: taskBytes.byteLength,
    artifactPath,
    sandboxRoot,
    toolCommand,
    toolInputDigest: sha256Bytes(toolInputBytes),
    toolInputByteLength: toolInputBytes.byteLength,
  });
}

export function isWorksiteCommandExecutionHelperPlan(
  task: WorksiteExecutionTask,
  value: unknown,
): value is WorksiteCommandExecutionHelperPlan {
  if (!isRecord(value) || !exactKeys(value, [
    "artifactPath", "attemptRef", "helperModulePath", "kind", "sandboxRoot", "schemaVersion",
    "taskManifestByteLength", "taskManifestDigest", "taskManifestPath", "toolCommand",
    "toolInputByteLength", "toolInputDigest",
  ]) || value.kind !== "worksite_command_execution_helper_plan" ||
    value.schemaVersion !== SCHEMA_VERSION || !nonempty(value.attemptRef) ||
    typeof value.toolCommand !== "string") return false;
  try {
    // Only the executable is read from retained command bytes. Every remaining
    // command word and all plan coordinates are rederived from task/attempt.
    const executableWord = /^'((?:[^']|'"'"')*)' /u.exec(value.toolCommand)?.[1];
    if (executableWord === undefined) return false;
    const executable = executableWord.replaceAll(`'"'"'`, "'");
    return same(value, helperPlanForExecutable(task, value.attemptRef, executable));
  } catch {
    return false;
  }
}

/** Full artifact and replay row law is independent of the raw Worker acknowledgment. */
function assertWorksiteCommandVectors(
  task: WorksiteExecutionTask,
  commandResults: readonly WorksiteCommandResult[],
  predicateObservations: readonly WorksitePredicateObservation[],
): void {
  if (!isWorksiteExecutionTask(task) ||
    !Array.isArray(commandResults) || !commandResults.every(isCommandResult) ||
    !Array.isArray(predicateObservations) || !predicateObservations.every(isPredicateObservation) ||
    commandResults.length !== task.commands.length ||
    !commandResults.every((result, ordinal) => {
      const declared = task.commands[ordinal];
      return declared !== undefined && result.ordinal === ordinal &&
        result.commandId === declared.commandId && result.executable === declared.executable &&
        same(result.args, declared.args) && result.relativeCwd === declared.relativeCwd &&
        same(result.environment, declared.environment) && result.timeoutMs === declared.timeoutMs &&
        result.terminationGraceMs === declared.terminationGraceMs &&
        result.reports.length === declared.expectedReports.length &&
        result.reports.every((report, reportOrdinal) => {
          const expected = declared.expectedReports[reportOrdinal];
          return expected !== undefined && report.ordinal === reportOrdinal &&
            report.commandOrdinal === declared.ordinal && report.commandId === declared.commandId &&
            report.expectedReportIdentity === expected.reportIdentity &&
            report.relativePath === expected.relativePath;
        });
    }) || predicateObservations.length !== task.outcomePredicates.length ||
    !predicateObservations.every((observation, ordinal) => {
      const declared = task.outcomePredicates[ordinal];
      return declared !== undefined && observation.ordinal === ordinal &&
        observation.predicateId === declared.predicateId &&
        observation.predicateKind === declared.predicateKind;
    })) {
    throw new TypeError("worksite command execution rows must preserve exact command, report, and predicate identity/order");
  }
  admitIJsonValue({ commandResults, predicateObservations }, "worksite command execution rows");

async function materializeSnapshot(
  task: WorksiteExecutionTask,
  snapshotRoot: string,
): Promise<Readonly<{
  snapshotRef: string;
  snapshotDigest: `sha256:${string}`;
  snapshotMembers: readonly WorksiteExecutionSnapshotMember[];
}>> {
  await mkdir(snapshotRoot);
  const members: WorksiteExecutionSnapshotMember[] = [];
  for (const [ordinal, protectedRow] of worksiteExecutionSources(task).entries()) {
    const sourcePath = await confinedExistingPath(
      task.workspaceAuthorityBasis.canonicalRoot,
      protectedRow.subject.relativePath,
      "file",
    );
    const bytes = await readFile(sourcePath);
    const digest = sha256Bytes(bytes);
    if (digest !== protectedRow.observation.fileDigest ||
      bytes.byteLength !== protectedRow.observation.byteLength) {
      throw new TypeError("snapshot source bytes differ from protected O1");
    }
    const targetPath = contained(snapshotRoot, protectedRow.subject.relativePath);
    await mkdir(dirname(targetPath), { recursive: true });
    await writeFile(targetPath, bytes, { flag: "wx" });
    const published = await readFile(targetPath);
    if (!published.equals(bytes)) throw new TypeError("snapshot member changed after create-only publication");
    members.push(Object.freeze({
      ...("sourceMemberRef" in protectedRow && "source" in protectedRow
        ? { kind: "worksite_command_forward_snapshot_member" as const, sourceMemberRef: protectedRow.sourceMemberRef, source: protectedRow.source }
        : "sourceMemberRef" in protectedRow
        ? { kind: "worksite_snapshot_member" as const, sourceMemberRef: protectedRow.sourceMemberRef }
        : { kind: "worksite_revision_snapshot_member" as const, designTargetRef: protectedRow.designTargetRef, source: protectedRow.source }),
      schemaVersion: "5.0.0" as const,
      ordinal,
      sourceObservationRef: protectedRow.observation.observationRef,
      sourceObservationDigest: protectedRow.observation.observationDigest,
      relativePath: protectedRow.subject.relativePath,
      byteLength: bytes.byteLength,
      digest,
    }));
  }
  const snapshotMembers = Object.freeze(members);
  const snapshotDigest = sha256Canonical(snapshotMembers as unknown as JsonValue);
  return Object.freeze({
    snapshotRef: `${worksiteExecutionIdentityPrefix(task, "snapshot")}/${snapshotDigest.slice("sha256:".length)}`,
    snapshotDigest,
    snapshotMembers,
  });

async function reportObservation(
